CREATE TABLE IF NOT EXISTS publicacoes_profissionais (id INT AUTO_INCREMENT PRIMARY KEY, profissional_id INT NOT NULL, conteudo TEXT NOT NULL, imagem_url VARCHAR(1000), ativo BOOLEAN DEFAULT TRUE, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (profissional_id) REFERENCES profissionais(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS curtidas_publicacoes (publicacao_id INT NOT NULL, usuario_id INT NOT NULL, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(publicacao_id,usuario_id), FOREIGN KEY(publicacao_id) REFERENCES publicacoes_profissionais(id) ON DELETE CASCADE, FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS comentarios_publicacoes (id INT AUTO_INCREMENT PRIMARY KEY, publicacao_id INT NOT NULL, usuario_id INT NOT NULL, comentario VARCHAR(1000) NOT NULL, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(publicacao_id) REFERENCES publicacoes_profissionais(id) ON DELETE CASCADE, FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS avaliacoes_profissionais (id INT AUTO_INCREMENT PRIMARY KEY, profissional_id INT NOT NULL, cliente_id INT NOT NULL, nota TINYINT NOT NULL, comentario VARCHAR(1000), criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, atualizado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY avaliacao_unica(profissional_id,cliente_id), FOREIGN KEY(profissional_id) REFERENCES profissionais(id) ON DELETE CASCADE, FOREIGN KEY(cliente_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS anuncios_profissionais (id INT AUTO_INCREMENT PRIMARY KEY, profissional_id INT NOT NULL, titulo VARCHAR(180) NOT NULL, texto VARCHAR(500), imagem_url VARCHAR(1000), link_url VARCHAR(1000), status ENUM('rascunho','pendente','aprovado','rejeitado','encerrado') DEFAULT 'pendente', inicio_em DATETIME, fim_em DATETIME, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(profissional_id) REFERENCES profissionais(id) ON DELETE CASCADE);
